// url.Parse percent-decodes %0A into Path and userinfo, so a remote URL can
// carry a raw newline into the line-based git-credential protocol. git takes
// the last value given for a key, so an injected "host=" would make the
// helper hand over another host's credentials, which we would then send to
// the endpoint that carried the injection. Upstream git refuses such URLs
// (check_url_component) and such values (credential_write_item) rather than
// escaping them, and http.c dies instead of continuing anonymously.
func TestCredentialInput_RejectsControlCharacters(t *testing.T) {
	parsed := func(raw string) *url.URL {
		t.Helper()
		u, err := url.Parse(raw)
		if err != nil {
			t.Fatalf("url.Parse(%q): %v", raw, err)
		}
		return u
	}

	tests := []struct {
		name     string
		ep       *url.URL
		username string
		password string
		wantKey  string
	}{
		{
			name:    "newline in path injects a host line",
			ep:      parsed("https://evil.example.com/repo%0Ahost=github.com"),
			wantKey: "path",
		},
		{
			name:    "carriage return in path",
			ep:      parsed("https://evil.example.com/repo%0Dhost=github.com"),
			wantKey: "path",
		},
		{
			name:    "NUL in path",
			ep:      parsed("https://evil.example.com/repo%00"),
			wantKey: "path",
		},
		{
			name:    "newline in embedded username",
			ep:      parsed("https://us%0Aer@evil.example.com/repo"),
			wantKey: "username",
		},
		{
			name:    "newline in embedded password",
			ep:      parsed("REDACTED"),
			wantKey: "password",
		},
		{
			name:     "newline in explicit username",
			ep:       parsed("https://example.com/repo"),
			username: "alice\nhost=github.com",
			password: "REDACTED",
			wantKey:  "username",
		},
		{
			name:     "newline in explicit password",
			ep:       parsed("https://example.com/repo"),
			username: "alice",
			password: "REDACTED",
			wantKey:  "password",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := credentialInput(tt.ep, tt.username, tt.password)
			if !errors.Is(err, ErrControlCharacter) {
				t.Fatalf("expected ErrControlCharacter, got err=%v input=%q", err, got)
			}
			if got != "" {
				t.Errorf("expected no request body, got %q", got)
			}
			if !strings.Contains(err.Error(), tt.wantKey) {
				t.Errorf("error %q does not name the offending component %q", err, tt.wantKey)
			}
		})
	}
}

// The error names the offending field but must never echo its value: for
// username and password that would leak a credential into logs and CI output.
func TestCredentialInput_ErrorOmitsFieldValue(t *testing.T) {
	ep := &url.URL{Scheme: "https", Host: "example.com"}

	_, err := credentialInput(ep, "alice", "REDACTED")
	if err == nil {
		t.Fatal("expected an error")
	}
	if strings.Contains(err.Error(), "REDACTED") {
		t.Errorf("error leaks the credential value: %q", err)
	}
}

func TestGitCredentialHelper_Lookup_InjectedURLNeverReachesHelper(t *testing.T) {
